      annotations: [
        {
          id: 'a3.29.1',
          kind: "concept",
          refs: ['g3.29.5', 'g3.29.9', 'g3.29.27'],
          lemma: "ὁ φίλος τοῦ νυμφίου",
          title: "The friend of the bridegroom",
          body: "The **friend of the bridegroom** — roughly the best man — arranges the wedding and stands aside for it; his gladness is to hear the groom’s voice and see the marriage made, not to be the centre himself. John casts his whole ministry in that role. Behind it lies a great Old Testament image: **God as the bridegroom of his people** (Hos 2:19; Isa 62:5). To call Jesus the bridegroom is quietly to give him God’s own part — and John could not be happier to decrease.",
        },
      ],
